create role authenticated;create role anon;create schema auth;create schema private;create schema storage;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table organizations(id uuid primary key);
create table profiles(id uuid primary key);
create table organization_members(organization_id uuid,user_id uuid,role text,status text,finance_role text default 'none',access_role_id uuid);
create table organization_access_roles(id uuid,organization_id uuid,capabilities text[],deleted_at timestamptz);
create function private.is_active_member(o uuid) returns boolean language sql stable security definer as $$select exists(select 1 from public.organization_members where organization_id=o and user_id=auth.uid() and status='active')$$;
create function private.can_manage_finance(o uuid) returns boolean language sql stable security definer as $$select exists(select 1 from public.organization_members where organization_id=o and user_id=auth.uid() and status='active' and (role='admin' or finance_role in('approver','treasurer','approver_treasurer')))$$;
grant usage on schema auth,private,storage to authenticated;
create table events(id uuid primary key,organization_id uuid,deleted_at timestamptz);
create table inbox_items(id uuid primary key,organization_id uuid,title text,description text,source text,status text default 'new',priority text default 'normal',created_by uuid,reviewer_id uuid,created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
alter table inbox_items enable row level security;
grant select on inbox_items to authenticated;
create table expenses(id uuid primary key default gen_random_uuid(),organization_id uuid,title text,category text,status text default 'planned',amount numeric(12,2),expense_date date,supplier text,invoice_number text,claimant_name text,notes text,event_id uuid,submitted_by uuid,created_by uuid,proof_url text,deleted_at timestamptz);
alter table expenses add constraint expenses_paid_requires_proof check(status not in('paid','reimbursed') or proof_url is not null);
alter table expenses enable row level security;
grant select,update on expenses to authenticated;
create policy fixture_expense_read on expenses for select to authenticated using(private.is_active_member(organization_id) and (submitted_by=auth.uid() or private.can_manage_finance(organization_id)));
create policy fixture_expense_update on expenses for update to authenticated using(private.can_manage_finance(organization_id)) with check(private.can_manage_finance(organization_id));
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,metadata jsonb,unique(bucket_id,name));
alter table storage.objects enable row level security;
grant select,insert,update,delete on storage.objects to authenticated;
